import json, numpy as np
S = json.load(open('head.json'))
w = json.load(open('wake_stats.json'))
st = json.load(open('static.json'))
H = 3.0
g = lambda u: w[str(u)]
f2 = lambda v: f'{v:.2f}'; f3 = lambda v: f'{v:.3f}'

S += [('h1', '4  计算结果与分析')]
S += [('h2', '4.1  气动性能')]
S += [('p', '对每个工况后 2 转（2.4 s）的转矩时间历程进行统计，得到平均转矩、转矩脉动、单位叶高功率及无量纲系数，结果列于表4。表中三维功率估计值为单位叶高功率乘以叶片高度 H = 3.0 m，未考虑端部损失和沿高度半径变化的影响，仅作为量级参考。')]
rows = [['工况', 'U∞ (m/s)', 'λ', '平均转矩 (N·m/m)', '转矩标准差 (N·m/m)', '功率 (W/m)', 'C_{p}', 'C_{T}', 'C_{D}', '三维功率估计 (W)']]
for k, u in enumerate((4, 6, 8, 10), 1):
    r = g(u)
    rows.append([f'工况{k}', f'{u}', f3(r['lam']), f3(r['Tm']), f3(r['Tstd']), f2(r['P']), f3(r['Cp']), f3(r['Ct']), f2(r['Cd']), f'{r["P"]*H:.1f}'])
S += [('table', '表4  四种风况下风轮气动性能统计结果', rows, [1.4, 1.3, 1.3, 1.9, 2.0, 1.5, 1.3, 1.3, 1.3, 2.0])]
cp = {u: g(u)['Cp'] for u in (4, 6, 8, 10)}
S += [('p', f'由表4可知：（1）在定转速条件下，风速由 4 m/s 增大到 10 m/s，叶尖速比 λ 由 0.59 降至 0.24，平均转矩由 {g(4)["Tm"]:.2f} N·m/m 增大到 {g(10)["Tm"]:.2f} N·m/m，单位叶高输出功率由 {g(4)["P"]:.2f} W/m 增大到 {g(10)["P"]:.2f} W/m。功率随风速增大而增大，但增长速度明显低于风速的三次方关系，8 m/s 到 10 m/s 之间功率仅增加约 {100*(g(10)["P"]/g(8)["P"]-1):.0f}%。')]
S += [('p', f'（2）风能利用系数 C_{{p}} 随叶尖速比呈先增大后减小的规律：λ = 0.39（6 m/s）时 C_{{p}} 最大，为 {cp[6]:.3f}；λ = 0.59（4 m/s）时为 {cp[4]:.3f}；而在高风速 10 m/s（λ = 0.24）时下降到 {cp[10]:.3f}。这说明对于定转速运行的阻力型风轮，高风速时转速相对偏低，叶片相对来流的“让流”速度不足，大量来流能量没有被转化为轴功，而是以尾流中的大尺度涡结构耗散掉；低风速时则叶尖速比偏高，返回叶片凸面的逆向阻力增大，平均转矩下降。因此该风轮更适合采用变转速（最大功率跟踪）控制，使叶尖速比保持在 0.35～0.45 附近。')]
S += [('p', f'（3）转矩脉动十分显著，各工况转矩标准差与平均转矩之比为 {min(g(u)["Tstd"]/g(u)["Tm"] for u in (4,6,8,10)):.2f}～{max(g(u)["Tstd"]/g(u)["Tm"] for u in (4,6,8,10)):.2f}，瞬时转矩在一个周期内出现负值，最大负转矩出现在 10 m/s 工况（{g(10)["Tmin"]:.2f} N·m/m）。这是二维截面计算的固有特点：三叶片在一个旋转周期内依次经历“凹面迎风—叶片间相互遮挡—凸面迎风”三个阶段。实际三维扭曲叶片沿高度方向各截面相位不同（总扭转角约 120°，恰好等于叶片间隔角），各截面转矩峰谷相互叠加抵消，整机转矩脉动将远小于二维截面结果，这也正是该风轮采用扭曲叶片设计的原因。转矩频谱主峰频率约为 {g(10)["fpk"]:.2f} Hz（10 m/s），与叶片通过频率 3n/60 = 2.5 Hz 一致。')]
S += [('p', f'（4）风轮所受平均阻力系数 C_{{D}} 在 {min(g(u)["Cd"] for u in (4,6,8,10)):.2f}～{max(g(u)["Cd"] for u in (4,6,8,10)):.2f} 之间，并随风速（即随 λ 减小）略有增大；侧向力系数为负（指向 −y 方向），对应尾流向 +y 方向偏转，这是旋转风轮的 Magnus 效应：风轮逆时针旋转时，下侧叶片顺流运动、上侧叶片逆流运动，两侧相对速度不同，导致流场不对称。')]

S += [('h2', '4.2  四种风况下的流场与尾流结构')]
S += [('p', '图2～图5分别给出四种风况计算结束时刻（t = 4.0 s）的瞬时速度幅值云图（a）、风轮附近瞬时涡量云图（b）以及后 2 转统计得到的时均流向速度剖面（c）。图中速度以来流风速 U∞ 无量纲化，坐标以风轮直径 D 无量纲化，阴影带表示风轮投影宽度（|y| < 0.5D）。')]
desc = {
    4: f'图2为低风速工况（U∞ = 4 m/s，λ = 0.59）。由于叶尖速比较大，叶片旋转速度与来流速度相当，叶片对流体的“搅动”作用较强，近尾迹内的剪切层被旋转叶片卷起形成一串尺度较小的涡，并明显向 +y 侧偏转。x/D = 1 处时均最低流速为 {g(4)["wake"]["1"]["umin"]:.2f}U∞，出现回流区；x/D = 4 处风轮投影范围内平均速度已恢复到 {g(4)["wake"]["4"]["uavg"]:.2f}U∞，x/D = 6 处恢复到 {g(4)["wake"]["6"]["uavg"]:.2f}U∞，尾流恢复较快，但尾流中心线向 +y 偏移约 {g(4)["wake"]["6"]["ymin"]:.1f}D。',
    6: f'图3为中低风速工况（U∞ = 6 m/s，λ = 0.39），此时风能利用系数最大。从涡量图可以看出，前进叶片凹面内形成稳定的高压驻涡，叶片尖端交替脱落正、负涡，尾流呈较规则的涡街形态。x/D = 1 处时均最低速度为 {g(6)["wake"]["1"]["umin"]:.2f}U∞，x/D = 2 处投影范围平均速度为 {g(6)["wake"]["2"]["uavg"]:.2f}U∞，x/D = 6 处为 {g(6)["wake"]["6"]["uavg"]:.2f}U∞。与 4 m/s 工况相比，风轮从来流中提取的能量更多，远尾迹速度亏损更大、恢复更慢。',
    8: f'图4为中高风速工况（U∞ = 8 m/s，λ = 0.29）。叶尖速比进一步减小，风轮接近“钝体”绕流状态，近尾迹回流最强，x/D = 1 处时均最低速度达到 {g(8)["wake"]["1"]["umin"]:.2f}U∞，该处投影范围平均速度仅 {g(8)["wake"]["1"]["uavg"]:.2f}U∞，脉动强度峰值也最大（{g(8)["wake"]["1"]["TI"]:.2f}U∞）。强烈的脉动增强了尾流与外部高速流之间的动量交换，因此尾流在 x/D = 4～6 之间快速恢复，x/D = 6 处投影范围平均速度恢复到 {g(8)["wake"]["6"]["uavg"]:.2f}U∞，尾流宽度明显扩张。',
    10: f'图5为高风速工况（U∞ = 10 m/s，λ = 0.24）。由于转速相对来流很低，风轮几乎相当于一个缓慢转动的钝体，叶片尖端脱落的大尺度涡结构（尺度约 0.5D～1D）在尾流中交替排列，形成典型的卡门涡街。时均剖面显示尾流较窄但亏损很深：x/D = 2 处时均最低速度仅 {g(10)["wake"]["2"]["umin"]:.2f}U∞，x/D = 6 处投影范围平均速度只恢复到 {g(10)["wake"]["6"]["uavg"]:.2f}U∞，x/D = 8 处为 {g(10)["wake"]["8"]["uavg"]:.2f}U∞，是四种工况中恢复最慢的。尾流偏转量也最小，说明叶尖速比越小，旋转引起的流场不对称性越弱。',
}
cap = {4: '图2  工况1（U∞ = 4 m/s）流场：(a) 瞬时速度幅值；(b) 近尾迹瞬时涡量；(c) 时均尾流速度剖面',
       6: '图3  工况2（U∞ = 6 m/s）流场：(a) 瞬时速度幅值；(b) 近尾迹瞬时涡量；(c) 时均尾流速度剖面',
       8: '图4  工况3（U∞ = 8 m/s）流场：(a) 瞬时速度幅值；(b) 近尾迹瞬时涡量；(c) 时均尾流速度剖面',
       10: '图5  工况4（U∞ = 10 m/s）流场：(a) 瞬时速度幅值；(b) 近尾迹瞬时涡量；(c) 时均尾流速度剖面'}
for u in (4, 6, 8, 10):
    S += [('fig', f'fig_U{u}.png', cap[u], 15.0)]
    S += [('p', desc[u])]

S += [('h2', '4.3  尾流特征对比')]
rows = [['工况', 'U∞ (m/s)', 'x/D = 1', 'x/D = 2', 'x/D = 4', 'x/D = 6', 'x/D = 8']]
for k, u in enumerate((4, 6, 8, 10), 1):
    rows.append([f'工况{k}', f'{u}'] + [f2(g(u)['wake'][x]['uavg']) for x in ('1', '2', '4', '6', '8')])
S += [('table', '表5  风轮投影范围（|y| < 0.5D）内时均流向速度 ū/U∞ 沿流向的恢复', rows)]
S += [('p', '综合图2～图5和表5，该垂直轴风力机尾流具有以下特征：')]
S += [('p', '（1）近尾迹（x/D ≤ 1）存在回流区。四种工况在 x/D = 1 处时均最低速度均为负值，投影范围平均速度只有 0.05～0.15U∞，说明阻力型风轮对来流的阻塞作用很强，近尾迹内速度亏损接近 90%。')]
S += [('p', f'（2）尾流恢复速度与风轮的能量提取和尾流混合强度有关。x/D = 6 处投影范围平均速度：4 m/s 工况为 {g(4)["wake"]["6"]["uavg"]:.2f}U∞，6 m/s 工况为 {g(6)["wake"]["6"]["uavg"]:.2f}U∞，8 m/s 工况为 {g(8)["wake"]["6"]["uavg"]:.2f}U∞，10 m/s 工况为 {g(10)["wake"]["6"]["uavg"]:.2f}U∞。4 m/s 工况叶尖速比大，旋转叶片对剪切层的搅动作用强；8 m/s 工况近尾迹速度脉动最强，与外部高速流的动量交换快，二者恢复都较快。6 m/s 工况风能利用系数最大，从来流中提取的动能最多，尾流亏损较大；10 m/s 工况叶尖速比最小，尾流以规则的大尺度涡街为主，中心区域低速流体不易被卷吸补充，恢复最慢。')]
S += [('p', '（3）尾流具有不对称性和偏转。由于风轮逆时针旋转，叶片在 −y 侧顺流运动、在 +y 侧逆流运动，尾流整体向 +y 侧偏转；叶尖速比越大，偏转越明显（4 m/s 工况在 x/D = 6 处偏移约 0.8D）。在风电场布置中，下游机组应考虑尾流偏转方向，适当错位布置，可减小尾流对下游机组的遮挡。')]
S += [('p', '（4）对风电场布置的启示：在本文计算范围内，x/D = 6 处尾流速度仍有 10%～37% 的亏损，按风功率与风速三次方的关系，正对尾流中心的下游机组功率损失可达 27%～75%。因此，若该型风力机按顺风向排列，机组间距宜大于 8D，或采用错列（交错）布置；另一方面，相邻两台反向旋转的垂直轴风力机近距离并排布置时，可利用尾流的相互作用提高整体效率，这是垂直轴风电场的研究热点。')]

S += [('h2', '4.4  结果可靠性检验')]
S += [('p', '为检验计算方法的可靠性，在风轮静止（ω = 0）的条件下，计算了 0°、30°、60°、90° 四个方位角的静态气动力（网格 D/48，来流 8 m/s），结果见表6。')]
rows = [['方位角', '静态转矩系数 C_T', '阻力系数 C_D', '侧向力系数 C_L']]
for a in ('0', '30', '60', '90'):
    rows.append([f'{a}°', f3(st[a]['Ct']), f2(st[a]['Cd']), f2(st[a]['Cl'])])
Cts = np.mean([st[a]['Ct'] for a in st])
S += [('table', '表6  静止风轮的静态气动力系数（不同方位角）', rows)]
S += [('p', f'由表6可知，静止风轮的阻力系数为 1.29～2.11，介于半圆柱形叶片凸面迎风（约 1.2）与凹面迎风（约 2.3）的经典阻力系数之间[1]，量级合理；静态转矩系数随方位角正负交替变化，平均值约为 {Cts:.3f}。在 0°～30° 方位角范围内，上游的返回叶片恰好遮挡了下方前进叶片的凹面，静态转矩为负，说明三叶片无重叠结构存在启动“死点”。这与 Savonius 风轮静态转矩随方位角周期性波动的实验规律一致，而实际风轮采用约 120° 的扭曲叶片，正是为了使整个叶高范围内总能有截面处于正转矩区，从而消除启动死点。')]
S += [('p', f'在动态工况下，本文计算的最大风能利用系数为 {max(cp.values()):.3f}，对应叶尖速比约 0.4。文献[1, 2]中 Savonius 型风轮的实验最大风能利用系数一般在 0.1～0.2 量级，最佳叶尖速比多在 0.7～1.0 之间。本文 C_{{p}} 偏低、最佳叶尖速比偏小，说明二维粗网格模型低估了前进叶片凹面的压差、高估了返回叶片的阻力，原因见第 5 节误差分析。总体来看，本文模拟得到的流场结构、气动力量级和随风况的变化趋势是合理的，可用于四种风况之间的对比分析，但 C_{{p}} 的绝对数值只能作为定性参考。')]
S += [('h1', '5  误差分析')]
S += [('p', '本文数值模拟结果与实际风力机性能之间的误差主要来源于以下几个方面：')]
S += [('p', '（1）二维简化误差。实际风轮为沙漏形扭曲叶片，各高度截面半径从 0.21 m 变化到 0.77 m，相位相差最大约 120°。二维模型只取等效半径截面，忽略了叶片扭曲引起的展向流动、端部绕流（叶尖涡）以及端环和导流罩的影响。二维计算中涡结构不能沿展向破碎，涡的强度和尺度偏大，导致转矩脉动和尾流涡街比实际偏强。')]
S += [('p', '（2）网格分辨率与叶片厚度误差。受计算资源限制，网格尺度为 D/64（约 14 mm），叶片厚度按 2 个网格（约 28 mm）处理，而实际叶片为薄壳结构；同时浸入边界在叶片表面附近采用光滑过渡，边界层无法解析，叶片表面存在约 2%～3% U∞ 的残余滑移速度，叶片凹面内的压力恢复被低估，这是 C_{p} 偏低的主要原因之一。')]
S += [('p', '（3）湍流模型误差。二维 Smagorinsky 大涡模拟不能正确描述三维湍流的能量级串，亚格子模型常数取经验值 0.17，对分离点位置和涡脱落频率有一定影响。实际风场来流含有一定湍流度，而本文入口采用均匀来流，会使尾流恢复偏慢。')]
S += [('p', '（4）边界条件与阻塞误差。计算域横向宽度为 8D，阻塞比为 12.5%，且采用周期边界，相当于一排横向间距 8D 的风力机，侧壁约束使风轮附近流速略有增加；出口采用边缘区强迫，x/D > 9.5 以后的流场受到人为强迫，因此尾流分析只取到 x/D = 8。')]
S += [('p', '（5）统计时间误差。受计算时间限制，每个工况计算 4.0 s（约 3.3 转），只用后 2 转作时均统计。对比相邻两转的平均转矩，相差约 10%～26%，时均尾流剖面也存在一定的统计波动，若延长统计时间（如 10 转以上），结果会更加可靠。')]
S += [('p', '（6）运行方式差异。本文采用定转速 50 r/min 计算，而实际小型风力机多为变转速运行，不同风速下实际叶尖速比与本文工况不同。若要得到完整的 C_{p}–λ 曲线，应在同一风速下改变转速进行一系列计算。')]

S += [('h1', '6  结论')]
S += [('p', f'本文以三叶片扭曲型垂直轴风力机为研究对象，从 IGS 三维模型中提取几何参数，建立二维等效截面模型，采用 LES 与浸入边界法对定转速 50 r/min 下 4、6、8、10 m/s 四种风况进行了非定常数值模拟，主要结论如下：')]
S += [('p', f'（1）定转速运行时，风速增大使叶尖速比降低，单位叶高功率由 {g(4)["P"]:.2f} W/m（4 m/s）增大到 {g(10)["P"]:.2f} W/m（10 m/s），但风能利用系数先增大后减小，在 λ ≈ 0.39（6 m/s）时达到最大值 {cp[6]:.3f}，高风速时下降到 {cp[10]:.3f}，说明该风轮宜采用变转速控制，使叶尖速比保持在 0.4 左右。')]
